"""Real browser schedule forms, explicit preview clocks and isolated scheduler ticks."""
import json
import sys

from test_acceptance_browser import browser, engine_url, isolated_url, pytestmark
from test_acceptance_browser_mapping import durable_runs


HELPERS=r"""
const triggers=async w=>{await open(w);await page.getByRole('button',{name:'Triggers',exact:true}).click();};
let previewAfter='2026-09-20T00:00:00Z';
await page.route('**/api/workflows/*/preview',async route=>{const body=route.request().postDataJSON();await route.continue({postData:JSON.stringify({...body,after:previewAfter})});});
const preview=async()=>{const pending=page.waitForResponse(r=>r.url().endsWith('/preview'));await page.getByRole('button',{name:'Preview next five',exact:true}).click();const response=await pending;return {status:response.status(),value:await response.json()};};
const saveSchedule=async w=>{const pending=page.waitForResponse(r=>r.url().endsWith('/api/workflows/'+w.id)&&r.request().method()==='PUT');await page.getByRole('button',{name:'Save draft',exact:true}).last().click();return pending;};
const raw=async(path,method,body)=>page.evaluate(async({path,method,body})=>{const boot=await(await fetch('/api/bootstrap')).json();const r=await fetch(path,{method,headers:{'Content-Type':'application/json','X-CSRF-Token':boot.csrf},body:JSON.stringify(body)});return {status:r.status,value:await r.json()};},{path,method,body});
const untilDone=async id=>{let result;const until=Date.now()+90000;do{result=await request('/api/workflow-runs/'+id);if(!['queued','running','cancelling'].includes(result.status))break;await page.waitForTimeout(150);}while(Date.now()<until);return result;};
"""


def clock_driver(tmp_path):
    code="import json,sys;from datetime import datetime;from taskconsole.store import Store;from taskconsole.workflows import WorkflowService;store=Store(sys.argv[1],'sqlite:///'+sys.argv[1]+'/browser.sqlite');service=WorkflowService(store);print(json.dumps([r['id'] for r in service.tick(datetime.fromisoformat(sys.argv[2].replace('Z','+00:00')))]))"
    return "const {execFileSync}=await import('node:child_process');const tick=at=>JSON.parse(execFileSync("+json.dumps(sys.executable)+",['-c',"+json.dumps(code)+","+json.dumps(str(tmp_path))+",at],{encoding:'utf8'}));"


def test_browser_weekday_protocol_and_chicago_locale_reload_are_exact(isolated_url):
    browser(isolated_url,HELPERS+r"""
 const w=await seed({nodes:[node('a')],edges:[]});await request('/api/workflows/'+w.id+'/publish','POST',{});await triggers(w);await page.getByLabel('Schedule',{exact:true}).selectOption('weekly');await page.getByLabel('Wed',{exact:true}).check();await page.getByLabel('Time',{exact:true}).fill('07:00');let result=await preview();assert.deepEqual(result.value.next_runs.slice(0,3),['2026-09-21T07:00:00+00:00','2026-09-23T07:00:00+00:00','2026-09-28T07:00:00+00:00']);assert.equal((await saveSchedule(w)).status(),200);let saved=await request('/api/workflows/'+w.id);assert.deepEqual(saved.schedule.weekdays,[0,2]);
 await page.getByLabel('Schedule',{exact:true}).selectOption('daily');await page.getByLabel('Time',{exact:true}).fill('07:00');await page.getByLabel('Timezone',{exact:true}).fill('America/Chicago');await page.getByLabel('Schedule enabled',{exact:true}).check();assert.equal((await saveSchedule(w)).status(),200);saved=await request('/api/workflows/'+w.id);const before=await preview();assert.equal(before.value.next_runs[0],'2026-09-20T12:00:00+00:00');assert.ok((await page.locator('.wf-preview').textContent()).includes('7:00'));await page.locator('[data-locale="zh-CN"]').click();await page.reload();await page.getByRole('button',{name:'触发器',exact:true}).click();assert.equal(await page.getByLabel('时间',{exact:true}).inputValue(),'07:00');assert.equal(await page.getByLabel('时区',{exact:true}).inputValue(),'America/Chicago');const chineseResponse=page.waitForResponse(r=>r.url().endsWith('/preview'));await page.getByRole('button',{name:'预览接下来五次',exact:true}).click();assert.deepEqual((await(await chineseResponse).json()).next_runs,before.value.next_runs);await page.locator('[data-locale="en"]').click();assert.deepEqual((await preview()).value.next_runs,before.value.next_runs);const after=await request('/api/workflows/'+w.id);assert.deepEqual(after.schedule,saved.schedule);assert.equal(after.timezone,saved.timezone);assert.equal(after.enabled,true);assert.deepEqual(await request('/api/workflow-runs'),[]);
 """)


