def test_browser_all_schedule_forms_roundtrip_without_stale_kind_fields(isolated_url):
    browser(isolated_url,HELPERS+r"""
 const w=await seed({nodes:[node('a')],edges:[]});await request('/api/workflows/'+w.id+'/publish','POST',{});await triggers(w);previewAfter='2026-09-20T00:07:00Z';
 const variants=[['manual',{},[]],['interval',{every:15,unit:'minutes',anchor:'2026-09-20T00:00:00Z'},['2026-09-20T00:15:00+00:00','2026-09-20T00:30:00+00:00']],['interval',{every:2,unit:'hours',anchor:'2026-09-20T00:00:00Z'},['2026-09-20T02:00:00+00:00','2026-09-20T04:00:00+00:00']],['daily',{time:'07:30'},['2026-09-20T07:30:00+00:00']],['weekly',{time:'07:30',weekdays:[0,3]},['2026-09-21T07:30:00+00:00','2026-09-24T07:30:00+00:00']],['monthly',{time:'07:30',day:15},['2026-10-15T07:30:00+00:00']],['monthly',{time:'07:30',day:'last'},['2026-09-30T07:30:00+00:00']],['once',{time:'07:30',date:'2026-09-21'},['2026-09-21T07:30:00+00:00']]];
 for(const [kind,values,expected] of variants){await page.getByLabel('Schedule',{exact:true}).selectOption(kind);if(values.every){await page.getByLabel('Every',{exact:true}).fill(String(values.every));await page.getByLabel('Time',{exact:true}).selectOption(values.unit);await page.getByLabel('Starting anchor',{exact:true}).fill(values.anchor);}else if(values.time)await page.getByLabel('Time',{exact:true}).fill(values.time);if(values.weekdays)await page.getByLabel('Thu',{exact:true}).check();if(values.day)await page.getByLabel('Day of month',{exact:true}).selectOption(String(values.day));if(values.date)await page.getByLabel('Date',{exact:true}).fill(values.date);let value=await preview();assert.equal(value.status,200);assert.deepEqual(value.value.next_runs.slice(0,expected.length),expected);if(kind==='manual'||kind==='once')assert.equal(value.value.next_runs.length,expected.length);assert.equal((await saveSchedule(w)).status(),200);const saved=await request('/api/workflows/'+w.id);const canonical={kind,...values};if(canonical.anchor)canonical.anchor=canonical.anchor.replace('Z','+00:00');assert.deepEqual(saved.schedule,canonical);assert.equal(saved.enabled,false);await triggers(w);assert.equal(await page.getByLabel('Schedule',{exact:true}).inputValue(),kind);assert.deepEqual((await preview()).value.next_runs,value.value.next_runs);assert.equal(await page.locator('input[name="cron"]').count(),0);}
 await page.getByLabel('Schedule',{exact:true}).selectOption('daily');await page.getByLabel('Multiple times (optional)',{exact:true}).fill('18:30, 07:00, 07:00');assert.equal((await saveSchedule(w)).status(),200);assert.deepEqual((await request('/api/workflows/'+w.id)).schedule.times,['07:00','18:30']);assert.deepEqual((await preview()).value.next_runs.slice(0,3),['2026-09-20T07:00:00+00:00','2026-09-20T18:30:00+00:00','2026-09-21T07:00:00+00:00']);assert.deepEqual(await request('/api/workflow-runs'),[]);
 """)


