def test_browser_delayed_and_out_of_order_previews_cannot_replace_current_form(isolated_url):
    browser(isolated_url,HELPERS+r"""
 const w=await seed({nodes:[node('a')],edges:[],schedule:{kind:'daily',time:'07:30'}});await triggers(w);await page.unroute('**/api/workflows/*/preview');let release,ready;let gate=new Promise(r=>release=r),observed=new Promise(r=>ready=r);let sequence=0;
 await page.route('**/api/workflows/*/preview',async route=>{const n=++sequence,body=route.request().postDataJSON();const response=await route.fetch({postData:JSON.stringify({...body,after:'2026-09-20T00:00:00Z'})});if(n===1){ready();await gate;}await route.fulfill({response});});await page.getByRole('button',{name:'Preview next five',exact:true}).click();await observed;await page.getByLabel('Timezone',{exact:true}).fill('Asia/Shanghai');await page.getByLabel('Time',{exact:true}).fill('08:00');const late=page.waitForResponse(r=>r.url().endsWith('/preview'));release();await late;await page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));assert.equal(await page.locator('.wf-preview time').count(),0);assert.ok((await page.locator('.wf-preview').textContent()).includes('Choose a schedule'));
 await page.unroute('**/api/workflows/*/preview');sequence=0;gate=new Promise(r=>release=r);observed=new Promise(r=>ready=r);await page.route('**/api/workflows/*/preview',async route=>{const n=++sequence,body=route.request().postDataJSON();const response=await route.fetch({postData:JSON.stringify({...body,after:n===1?'2026-09-20T00:00:00Z':'2026-09-21T00:00:00Z'})});if(n===1){ready();await gate;}await route.fulfill({response});});await page.getByRole('button',{name:'Preview next five',exact:true}).click();await observed;const newest=await preview();assert.equal(newest.value.next_runs[0],'2026-09-22T00:00:00+00:00');await page.locator('.wf-preview time').first().waitFor();assert.equal(await page.locator('.wf-preview time').first().getAttribute('datetime'),newest.value.next_runs[0]);const older=page.waitForResponse(r=>r.url().endsWith('/preview'));release();await older;await page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));assert.equal(await page.locator('.wf-preview time').first().getAttribute('datetime'),newest.value.next_runs[0]);assert.equal(await page.getByLabel('Timezone',{exact:true}).inputValue(),'Asia/Shanghai');assert.equal(await page.getByLabel('Time',{exact:true}).inputValue(),'08:00');assert.deepEqual(await request('/api/workflow-runs'),[]);
 """)
